CREATE FUNCTION public.org_sync_sme_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid;BEGIN IF TG_OP='DELETE' THEN SELECT user_id INTO uid FROM org_people WHERE id=OLD.person_id;IF OLD.permission='sme' THEN DELETE FROM assessment_access WHERE battery_id=OLD.role_id AND user_id=uid AND permission='sme';END IF;RETURN OLD;END IF;SELECT user_id INTO uid FROM org_people WHERE id=NEW.person_id;IF uid IS NOT NULL AND NEW.permission='sme' AND EXISTS(SELECT 1 FROM assessment_batteries WHERE id=NEW.role_id) THEN INSERT INTO assessment_access(battery_id,user_id,permission,source_id) VALUES(NEW.role_id,uid,'sme',NEW.source_id) ON CONFLICT(battery_id,user_id,permission) DO UPDATE SET source_id=excluded.source_id;END IF;RETURN NEW;END $$;
CREATE TRIGGER sync_sme_access AFTER INSERT OR UPDATE OR DELETE ON org_assignments FOR EACH ROW EXECUTE FUNCTION org_sync_sme_access();
CREATE FUNCTION public.org_sme_link_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.permission='sme' AND EXISTS(SELECT 1 FROM assessment_batteries WHERE id=NEW.role_id) AND NOT EXISTS(SELECT 1 FROM assessment_batteries b CROSS JOIN LATERAL jsonb_array_elements(b.payload->'sources') s WHERE b.id=NEW.role_id AND s->>'id'=NEW.source_id) THEN RAISE EXCEPTION 'Choose a source in this job role';END IF;RETURN NEW;END $$;
CREATE TRIGGER sme_link_guard BEFORE INSERT OR UPDATE ON org_assignments FOR EACH ROW EXECUTE FUNCTION org_sme_link_guard();